#include <bits/stdc++.h>
using namespace std;

int main() {
    int rows, cols;
    scanf("%d %d", &rows, &cols);
    vector<vector<int>> a(rows, vector<int>(cols));
    for (auto& row : a) for (auto& x : row) scanf("%d", &x);
    vector<vector<char>> seen(rows, vector<char>(cols, 0)), pop(rows, vector<char>(cols, 0));
    int dx[] = {-1, 1, 0, 0}, dy[] = {0, 0, -1, 1};
    // Mark every same-color component of size >= 3 on the original board.
    for (int r = 0; r < rows; r++)
        for (int c = 0; c < cols; c++) {
            if (seen[r][c]) continue;
            int color = a[r][c];
            vector<pair<int, int>> comp{{r, c}};
            seen[r][c] = 1;
            for (size_t h = 0; h < comp.size(); h++) {
                auto [x, y] = comp[h];
                for (int d = 0; d < 4; d++) {
                    int nx = x + dx[d], ny = y + dy[d];
                    if (nx >= 0 && nx < rows && ny >= 0 && ny < cols && !seen[nx][ny] && a[nx][ny] == color) {
                        seen[nx][ny] = 1;
                        comp.push_back({nx, ny});
                    }
                }
            }
            if (comp.size() >= 3) for (auto [x, y] : comp) pop[x][y] = 1;
        }
    // Drop survivors to the bottom of each column, keeping their order.
    for (int c = 0; c < cols; c++) {
        int w = rows - 1;
        for (int r = rows - 1; r >= 0; r--) if (!pop[r][c]) a[w--][c] = a[r][c];
        while (w >= 0) a[w--][c] = 0;
    }
    string out;
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) { if (c) out += ' '; out += to_string(a[r][c]); }
        out += '\n';
    }
    fputs(out.c_str(), stdout);
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StringTokenizer st = new StringTokenizer(new String(System.in.readAllBytes()));
        int rows = Integer.parseInt(st.nextToken()), cols = Integer.parseInt(st.nextToken());
        int[][] a = new int[rows][cols];
        for (int r = 0; r < rows; r++) for (int c = 0; c < cols; c++) a[r][c] = Integer.parseInt(st.nextToken());
        boolean[][] seen = new boolean[rows][cols], pop = new boolean[rows][cols];
        int[] dx = {-1, 1, 0, 0}, dy = {0, 0, -1, 1};
        int[] comp = new int[rows * cols];
        // Mark every same-color component of size >= 3 on the original board.
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++) {
                if (seen[r][c]) continue;
                int color = a[r][c], size = 0;
                comp[size++] = r * cols + c;
                seen[r][c] = true;
                for (int h = 0; h < size; h++) {
                    int x = comp[h] / cols, y = comp[h] % cols;
                    for (int d = 0; d < 4; d++) {
                        int nx = x + dx[d], ny = y + dy[d];
                        if (nx >= 0 && nx < rows && ny >= 0 && ny < cols && !seen[nx][ny] && a[nx][ny] == color) {
                            seen[nx][ny] = true;
                            comp[size++] = nx * cols + ny;
                        }
                    }
                }
                if (size >= 3) for (int h = 0; h < size; h++) pop[comp[h] / cols][comp[h] % cols] = true;
            }
        // Drop survivors to the bottom of each column, keeping their order.
        for (int c = 0; c < cols; c++) {
            int w = rows - 1;
            for (int r = rows - 1; r >= 0; r--) if (!pop[r][c]) a[w--][c] = a[r][c];
            while (w >= 0) a[w--][c] = 0;
        }
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) { if (c > 0) sb.append(' '); sb.append(a[r][c]); }
            sb.append('\n');
        }
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() int { sc.Scan(); v, _ := strconv.Atoi(sc.Text()); return v }
	rows, cols := next(), next()
	a := make([][]int, rows)
	seen := make([][]bool, rows)
	pop := make([][]bool, rows)
	for r := range a {
		a[r] = make([]int, cols)
		seen[r] = make([]bool, cols)
		pop[r] = make([]bool, cols)
		for c := range a[r] {
			a[r][c] = next()
		}
	}
	dx, dy := []int{-1, 1, 0, 0}, []int{0, 0, -1, 1}
	// Mark every same-color component of size >= 3 on the original board.
	for r := 0; r < rows; r++ {
		for c := 0; c < cols; c++ {
			if seen[r][c] {
				continue
			}
			color := a[r][c]
			comp := [][2]int{{r, c}}
			seen[r][c] = true
			for h := 0; h < len(comp); h++ {
				x, y := comp[h][0], comp[h][1]
				for d := 0; d < 4; d++ {
					nx, ny := x+dx[d], y+dy[d]
					if nx >= 0 && nx < rows && ny >= 0 && ny < cols && !seen[nx][ny] && a[nx][ny] == color {
						seen[nx][ny] = true
						comp = append(comp, [2]int{nx, ny})
					}
				}
			}
			if len(comp) >= 3 {
				for _, p := range comp {
					pop[p[0]][p[1]] = true
				}
			}
		}
	}
	// Drop survivors to the bottom of each column, keeping their order.
	for c := 0; c < cols; c++ {
		w := rows - 1
		for r := rows - 1; r >= 0; r-- {
			if !pop[r][c] {
				a[w][c] = a[r][c]
				w--
			}
		}
		for ; w >= 0; w-- {
			a[w][c] = 0
		}
	}
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	for r := 0; r < rows; r++ {
		for c := 0; c < cols; c++ {
			if c > 0 {
				out.WriteByte(' ')
			}
			out.WriteString(strconv.Itoa(a[r][c]))
		}
		out.WriteByte('\n')
	}
}
